				return
			end

			local o = self.Folder .. "/themes/" .. w

			if not isfile(o) then
				return nil
			end

			local w = readfile(o)
			local o, i = pcall(Z.JSONDecode, Z, w)

			if not o then
				return nil
			end

			return i
		end
		function themeManager:SaveCustomTheme(w)
			if not w or w:gsub(" ", "") == "" then
				return self.Library:Notify("Invalid file name for theme (empty)", 3)
			end

			local o = {}
			local i = { "Contrast", "Saturation", "Brightness", "BlurSize", "FontColor", "RiskColor", "MainColor", "AccentColor", "BackgroundColor", marketplaceService, "ItemType", "SwordColor", "BackTransparency", "BackColor", "SwordTransparency", "SwordReflectance", "SwordMaterial", "SwordSpeed" }

			for z, z in next, i do
				if (options[z]) then
					if not z:find("Color") then
						o[z] = options[z].Value
					else
						o[z] = options[z].Value:ToHex()
					end
				end
			end

			writefile(self.Folder .. "/themes/" .. w, Z:JSONEncode(o))
		end
		function themeManager:ReloadCustomThemes()
			local w = listfiles(self.Folder .. "/themes")
			local z = {}

			for M = 1, #w do
				local Z = w[M]

				if Z:sub(-5.0) == ".json" then
					local w = Z:find(".json", 1, true)
					local M = Z:sub(w, w)

					while M ~= "/" and M ~= "\\" and M ~= "" do
						w = w - 1
						M = Z:sub(w, w)
					end

					if M == "/" or M == "\\" then
						table.insert(z, Z:sub(w + 1))
					end
				end
			end

			return z
		end
		function themeManager:SetLibrary(w)
			self.Library = w
		end
		function themeManager:BuildFolderTree()
			local w = {}
			local z = self.Folder:split("/")

			for M = 1, #z do
				w[#w + 1] = table.concat(z, "/", 1, M)
			end

			table.insert(w, self.Folder .. "/themes")

			for z = 1, #w do
				local M = w[z]

				if not isfolder(M) then
					makefolder(M)
				end
			end
		end
		function themeManager:SetFolder(w)
			self.Folder = w
			self:BuildFolderTree()
		end
		function themeManager:CreateGroupBox(w)
			assert(self.Library, "Must set ThemeManager.Library first!")

			return w:AddLeftTabbox()
		end
		function themeManager:ApplyToTab(w)
			assert(self.Library, "Must set ThemeManager.Library first!")

			local z = self:CreateGroupBox(w)

			self:CreateThemeManager(z)
		end
		function themeManager:ApplyToGroupbox(w)
			assert(self.Library, "Must set ThemeManager.Library first!")
			self:CreateThemeManager(w)
		end
	end

	getgenv().ThemeManager = themeManager
end)()

