local t73 = {
	Rain = "rbxassetid://9112858162",
	["Heavy Rain"] = "rbxassetid://9064263922",
	["Light Rain And Thunder"] = "rbxassetid://9120018695",
	["Forest Rain Night"] = "rbxassetid://5356133579",
	["Windy Day"] = "rbxassetid://159798309",
	City = "rbxassetid://238385471"
}
local ambience = v1686:AddTab("ambience")

ambience:AddToggle("ambience_enabled", {
	Text = "enabled",
	Default = false
})

local t74 = {}

for k in t73, nil, nil do
	table.insert(t74, k)
end

table.sort(t74, function(p258, p259)
	return #p258 < #p259
end)
ambience:AddDropdown("ambience_value", {
	Text = "selected",
	Values = t74,
	Default = "Heavy Rain"
})
