	Max = 10,
	Rounding = 1,
	Suffix = "db",
	Compact = true
})

local Sound = guiService("Sound", {
	Parent = game:GetService("SoundService"),
	Looped = true,
	Volume = 0.5,
	SoundId = t73["Heavy Rain"]
})

for _, v in {
	Toggles.ambience_enabled,
	Options.ambience_volume,
	Options.ambience_value
}, nil, nil do
	v:OnChanged(function()
		if Sound.SoundId ~= t73[Options.ambience_value.Value] then
			Sound.TimePosition = 0
		end

		Sound.Playing = Toggles.ambience_enabled.Value
		Sound.Volume = Options.ambience_volume.Value
		Sound.SoundId = t73[Options.ambience_value.Value]
	end)
end
end

