	Default = 0.3,
	Min = 0,
	Max = 2,
	Suffix = "db",
	Rounding = 1,
	Compact = true
})
v1787:AddSlider("shoot_sound_start", {
	Text = "start position",
	Default = 0,
	Min = 0,
	Max = 100,
	Suffix = "%",
	Rounding = 0,
	Compact = true
})
v1787:SetupDependencies({ {
	Toggles.shoot_sound_change,
	true
} })
v1787:AddButton("preview sound", function()
	local Value = Options.shoot_sound_change_value.Value

	if Value ~= "custom" then
		if not connectionsList.sounds.shoot[Value] then
			return
		end
	end

	local Sound = Instance.new("Sound", game:GetService("SoundService"))

	Sound.SoundId = connectionsList.sounds.shoot[Value] or "rbxassetid://" .. tostring(Options.shoot_sound_custom_value.Value)

	local Value2 = Options.shoot_sound_volume.Value

	Sound.PlaybackSpeed = Options.shoot_sound_speed.Value
	Sound.Volume = Value2
	Sound.TimePosition = Sound.TimeLength * (Options.shoot_sound_start.Value / 100)
	Sound:Play()
	task.delay(1 + Sound.TimeLength, function()
		Sound:Destroy()
	end)
end)
end

