local function v1809(p279)
	local t79 = {}
	local class = p279 and p279.class

	for k, v in module3.Items, nil, nil do
		if table.find(v1808, k) and (not class or v.Class == class) then
			table.insert(t79, k)
		end
	end

	table.sort(t79, function(p280, p281)
		return #p280 > #p281
	end)

	if not class then
		return t79, nil
	end

	local v1814

	for _, v in t79, nil, nil do
		if table.find(module2.DEFAULT_WEAPONS, v) then
			v1814 = v
		end
	end

	return t79, v1814
end

