local chat_spam = connectionsList.chat_spam

v1833:AddToggle("chat_spam_enabled", {
	Text = "enabled",
	Default = false
})
v1833:AddToggle("chat_spam_order", {
	Text = "in order",
	Tooltip = "chats go in order of creation, not randomly",
	Default = false
})
v1833:AddDropdown("chat_spam_mode", {
	Values = { "custom" },
	Default = "custom",
	Text = "chat mode"
})
v1833:AddDropdown("chat_spam_text", {
	Values = {},
	Multi = true,
	Illegal = true,
	Text = "random custom text",
	AllowNull = true,
	Callback = function(p282)
		local custom = {}

		for k, v in p282, nil, nil do
			if v then
				table.insert(custom, k)
			end
		end

		chat_spam.default.custom = custom
		Options.chat_spam_text:SetValues(custom)
	end
})
v1833:AddInput("chat_spam_input", {
	Numeric = false,
	Finished = true,
	Text = "add custom text",
	Placeholder = "message...",
	Callback = function(p283)
		if #p283 == 0 then
			return
		end

		if Options.chat_spam_text.Value[p283] then
			return
		end

		table.insert(Options.chat_spam_text.Values, p283)
		Options.chat_spam_text.Value[p283] = true
		Options.chat_spam_text:SetValue(Options.chat_spam_text.Value)
		Options.chat_spam_text:SetValues(Options.chat_spam_text.Values)
	end
})

local function v1838()
	local t82 = {}

	for _, v in error_.listfiles("chat") do
		local parts = readfile(v):split("\n")

		if #parts == 0 then
			Library:Notify("invalid file for chat spam:" .. v)
		else
			local parts2 = v:split("\\")

			t82[parts2[#parts2]] = parts
		end
	end

	local Values = Options.chat_spam_mode.Values

	for _, v in Values, nil, nil do
		if not (t82[v] or chat_spam.default[v]) then
			table.remove(Values, table.find(Values, v))
			chat_spam.messages[v] = nil
		end
	end

	for k, v in t82, nil, nil do
		if not table.find(Values, k) then
			table.insert(Values, k)
		end

		chat_spam.messages[k] = v
	end

	for k in chat_spam.default, nil, nil do
		if not table.find(Values, k) then
			table.insert(Values, k)
		end
	end

	Options.chat_spam_mode:SetValues(Values)
end

v1838()
v1833:AddButton("refresh modes", v1838)
end

