connectionsList.effects.hit_effects:register("fortnite damage", function(p421, p422)
	local Parent = p421.Parent

	if not Parent then
		return
	end

	local Value4 = Options.hit_effects_settings.Value
	local stackDamageTogether = Value4["stack damage together"]
	local v2312 = t112[Parent]

	if v2312 and stackDamageTogether then
		v2312[3]:Destroy()
		p422 += v2312[1]
		pcall(task.cancel, v2312[2])
	end

	local Part = Instance.new("Part", workspace)

	Part.CanCollide = false
	Part.CanTouch = false
	Part.CanQuery = false
	Part.Anchored = true
	Part.Transparency = 1

	local uDim2 = stackDamageTogether and v2312 and v2312[4]

	if not uDim2 then
		if stackDamageTogether then
			uDim2 = UDim2.fromOffset(25, -25)
		else
			local n127 = 30
			local v2316 = math.random(-n127, n127)

			if v2316 > 0 then
				v2316 += 30
			end

			uDim2 = UDim2.fromOffset(v2316, math.random(-n127, n127))
		end
	end

	Part.Position = p421.Position + vector3
	t112[Parent] = {
		p422,
		task.spawn(function()
			local clone = BillboardGui:Clone()

			clone.Parent = Part
			clone.Adornee = Part

			local parts = tostring(p422):split("")
			local v2319
			local t113 = {}
			local cycleColorsForText = Value4["cycle colors for text"] and n126 or 0

			for _, v in parts, nil, nil do
				cycleColorsForText = cycleColorsForText % 3 + 1

				local clone2 = instance:Clone()
				local TextLabel2 = clone2.TextLabel

				TextLabel2.TextColor3 = Options["hit_effects_col_" .. cycleColorsForText].Value
				TextLabel2.Text = v
				clone2.Parent = clone
				TextLabel2.Rotation = math.random(-2, 2)

				if v2319 then
					v2319 += TextLabel2.TextBounds.X
				else
					v2319 = -TextLabel2.TextBounds.X
				end

				clone2.Position = clone2.Position + uDim2 + UDim2.fromOffset(v2319, 0)
				table.insert(t113, TextLabel2)
			end

			n126 = cycleColorsForText

			local UIScale = clone.UIScale

			UIScale.Scale = stackDamageTogether and v2312 and 0.75 or 0
			TweenService:Create(UIScale, tweenInfo, {
				Scale = 1
			}):Play()
			task.wait(0.7 + math.random() * 0.5)

			local v2327 = #t113

			for k, v in t113, nil, nil do
				local v2330 = k / v2327 > 0.5 and 1 or -1
				local Position = v.Position
				local vector2 = Vector2.new(Position.X.Offset, Position.Y.Offset)
				local n128 = 130
				local n129 = 0.93
				local textTransparency = 0
				local vector22 = Vector2.new(v2330 * 75, 0)
				local connection

				connection = RunService.RenderStepped:Connect(function(dt)
					if textTransparency > 1 then
						return connection:Disconnect()
					end

					vector22 = Vector2.new(vector22.X - vector22.X * n129 * dt, vector22.Y + n128 * dt)
					vector2 += vector22 * dt
					v.Position = UDim2.new(0.5, vector2.X, 0.5, vector2.Y)
					v.TextTransparency = textTransparency
					v.Rotation = v2330 * 360 * math.exp(textTransparency)
					textTransparency += dt
				end)
			end

			task.wait(1)
			Part:Destroy()
			t112[Parent] = nil
		end),
		Part,
		uDim2
	}
end)

